        # TODO(1.10): update message to remove "as well as penalty=None".
        raise ValueError(
            "C=np.inf as well as penalty=None is not supported for the liblinear solver"
        )

    return solver, dual

def _check_solver(solver, penalty, dual, warn_depr=False):
    if solver == "liblinear" and warn_depr:
        warnings.warn(
            (
                "The solver 'liblinear' was deprecated in version 1.10 and will "
                "be removed in 1.12. For 'l1_ratio > 0', the new solvers 'newton-cd' "
                "and 'newton-cd-gram' are good replacements."
            ),
            FutureWarning,
        )
    if isinstance(dual, str) and dual == "deprecated":
        dual = False
    elif warn_depr:
        warnings.warn(
            (
                "The parameter 'dual' was deprecated in version 1.10 and will "
                "be removed in 1.12."
            ),
            FutureWarning,
        )

    if solver not in (
        "liblinear",
        "newton-cd",
        "newton-cd-gram",
        "saga",
    ) and penalty not in ("l2", None):
        raise ValueError(
            f"Solver '{solver}' supports only 'l2' or None penalties, got {penalty} "
            "penalty."
        )
    if solver != "liblinear" and dual:
        raise ValueError(f"Solver {solver} supports only dual=False, got dual={dual}")

    if penalty == "elasticnet" and solver not in (
        "saga",
        "newton-cd",
        "newton-cd-gram",
    ):
        raise ValueError(
            "Only solvers 'newton-cd', 'newton-cd-gram' and 'saga' support elasticnet "
            f"penalty, got solver={solver}."
        )

    if solver == "liblinear" and penalty is None:
        # TODO(1.10): update message to remove "as well as penalty=None".
        raise ValueError(
            "C=np.inf as well as penalty=None is not supported for the liblinear solver"
        )

    return solver, dual

def _swapaxes(array, axis1, axis2, /, xp=None):
    xp, _ = get_namespace(array)
    if hasattr(xp, "swapaxes"):
        return xp.swapaxes(array, axis1, axis2)

    ndim = array.ndim
    a1 = axis1 if axis1 >= 0 else axis1 + ndim
    a2 = axis2 if axis2 >= 0 else axis2 + ndim
    axes = list(range(ndim))
    axes[a1], axes[a2] = axes[a2], axes[a1]
    return xp.permute_dims(array, axes=tuple(axes))

def _unravel_index(indices, shape, /, xp=None):
    # TODO: remove this and use the respective array-api-extra function when
    # version 0.11.1 is released.
    # https://data-apis.org/array-api-extra/generated/array_api_extra.unravel_index.html
    xp, _ = get_namespace(indices)
    if hasattr(xp, "unravel_index"):
        return xp.unravel_index(indices, shape)

    coordinates = []
    for dim in reversed(shape):
        coordinates.append(indices % dim)
        indices = indices // dim
    return tuple(reversed(coordinates))

